_LEGACY = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2}) ([0-9]{2}):([0-9]{2}):([0-9]{2})")


def parse_iso(text: str) -> datetime | None:
    """An ISO 8601 time with `Z` or an offset (possibly with a fraction), else None."""
    m = _ISO.fullmatch(text)
    if not m:
        return None
    try:
        y, mo, d, h, mi, s = (int(m.group(i)) for i in range(1, 7))
        frac = (m.group(7) or "")[:6].ljust(6, "0")
        if m.group(8):
            tz = timezone.utc
        else:
            oh, om = int(m.group(10)), int(m.group(11) or 0)
            if oh > 23 or om > 59:
                return None
            delta = timedelta(hours=oh, minutes=om)
            tz = timezone(delta if m.group(9) == "+" else -delta)
        return datetime(y, mo, d, h, mi, s, int(frac), tzinfo=tz)
    except ValueError:
        return None


def parse_state_time(value) -> datetime | None:
    """A time in state.json: the form of `parse_iso`, or release 1.2's UTC form; else None."""
    if not isinstance(value, str):
        return None
    t = parse_iso(value)
    if t is not None:
