"""policy.ini (docs/policy.md)."""

import re
from dataclasses import dataclass
from datetime import timedelta, timezone
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

KEYS = ("max_size", "max_age", "naming", "offset", "compress_after", "keep", "keep_days")


@dataclass(frozen=True)
class Settings:
    max_size: int | None = None  # bytes; None is off
    max_age: timedelta | None = None
    naming: str = "numbered"
    offset: timezone = timezone.utc
    compress_after: int = 1
    keep: int = 5
    keep_days: int | None = None


class Policy:
    def __init__(self, defaults: dict, sections: dict):
        self.defaults = defaults
        self.sections = sections  # stream name -> {key: value}

    def streams(self) -> set[str]:
        return set(self.sections)

    def settings(self, name: str) -> Settings:
        merged = dict(self.defaults)
        merged.update(self.sections.get(name, {}))
        return Settings(**merged)


def _bad(path: Path, lineno: int, why: str) -> DataError:
    return DataError("policy", f"{path.name}:{lineno}: {why}")


def _size(v):
    m = re.fullmatch(r"([0-9]+)([KkMmGg]?)", v)
    if not m:
        raise ValueError(v)
    unit = {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m.group(2).lower()]
    return int(m.group(1)) * unit


def _off_or(parse):
    return lambda v: None if v == "off" else parse(v)


def _duration(v):
    m = re.fullmatch(r"([0-9]+)([mhd])", v)
    if not m:
        raise ValueError(v)
    unit = {"m": timedelta(minutes=1), "h": timedelta(hours=1), "d": timedelta(days=1)}[m.group(2)]
    return int(m.group(1)) * unit


def _naming(v):
    if v not in ("numbered", "dated"):
        raise ValueError(v)
    return v


def _offset(v):
    m = re.fullmatch(r"([+-])([0-9]{2}):([0-9]{2})", v)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        raise ValueError(v)
    delta = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return timezone(delta if m.group(1) == "+" else -delta)


def _count(minimum):
    def parse(v):
        if not re.fullmatch(r"[0-9]+", v) or int(v) < minimum:
            raise ValueError(v)
        return int(v)

    return parse


PARSERS = {
    "max_size": _off_or(_size),
    "max_age": _off_or(_duration),
    "naming": _naming,
    "offset": _offset,
    "compress_after": _count(0),
    "keep": _count(1),
    "keep_days": _off_or(_count(1)),
}


def load(path: Path) -> Policy:
    if not path.exists():
        return Policy({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise DataError("policy", f"{path.name}: {e}") from None
    defaults: dict = {}
    sections: dict = {}
    seen_defaults = False
    current = None
    for lineno, raw in enumerate(text.split("\n"), 1):
        line = raw.rstrip("\r")
        if line.strip() == "" or line[0] in "#;":
            continue
        if line.startswith("["):
            m = re.fullmatch(r"\[(defaults|stream ([^\]]*))\][ \t]*", line)
            if not m:
                raise _bad(path, lineno, f"bad section line: {line}")
            if m.group(2) is None:
                if seen_defaults:
                    raise _bad(path, lineno, "section [defaults] given twice")
                seen_defaults = True
                current = defaults
            else:
                name = m.group(2)
                if not streams.valid(name):
                    raise _bad(path, lineno, f"not a stream name: {name}")
                if name in sections:
                    raise _bad(path, lineno, f"section [stream {name}] given twice")
                current = sections[name] = {}
            continue
        if current is None:
            raise _bad(path, lineno, "setting outside a section")
        key, sep, value = line.partition("=")
        key, value = key.strip(" \t"), value.strip(" \t")
        if not sep or key not in PARSERS:
            raise _bad(path, lineno, f"unknown key or bad line: {line}")
        if key in current:
            raise _bad(path, lineno, f"key {key} given twice")
        try:
            current[key] = PARSERS[key](value)
        except ValueError:
            raise _bad(path, lineno, f"bad value for {key}: {value}") from None
    return Policy(defaults, sections)

"""rotate (docs/rotate.md)."""

import gzip
import re
from dataclasses import dataclass
from datetime import date, datetime
from pathlib import Path

from logkeep import dates, policy, streams
from logkeep.errors import DataError, Refused

_NUMBERED = re.compile(r"([1-9][0-9]*)(\.gz)?")
_DATED = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?")


@dataclass
class Item:
    """One archive of a stream, before or after the run."""

    order: tuple  # sorts the newest first
    gz: bool
    old: str | None  # file name before the run; None for the new archive
    base: str = ""  # dated: the name without `.gz`
    day: date | None = None
    k: int = 1
    time_text: str | None = None
    final: str = ""
    compress: bool = False


# ---------------------------------------------------------------- state checks

def check_state(doc: dict, existing: set[str]) -> None:
    for name in existing:
        entry = doc["streams"].get(name)
        if entry is None:
            continue
        if "opened" in entry and dates.parse_state_time(entry["opened"]) is None:
            raise DataError("state", f"{name}: opened is not a time")
        if "archives" in entry:
            archives = entry["archives"]
            if not isinstance(archives, dict):
                raise DataError("state", f"{name}: archives is not an object")
            for key, value in archives.items():
                if dates.parse_state_time(value) is None:
                    raise DataError("state", f"{name}: time of {key} is not a time")
        if "rotations" in entry:
            r = entry["rotations"]
            if type(r) is not int:
                raise DataError("state", f"{name}: rotations is not a whole number")


# -------------------------------------------------------------------- archives

def scan(data: Path, name: str, naming: str) -> list[Item]:
    """The archives of a stream, newest first."""
    d = streams.logs_dir(data)
    prefix = f"{name}.log."
    found: dict[tuple, Item] = {}
    if d.is_dir():
        for p in d.iterdir():
            fname = p.name
            if not fname.startswith(prefix) or not p.is_file():
                continue
            rest = fname[len(prefix):]
            if naming == "numbered":
                m = _NUMBERED.fullmatch(rest)
                if not m:
                    continue
                n = int(m.group(1))
                item = Item(order=(n,), gz=bool(m.group(2)), old=fname)
                place = (n,)
            else:
                m = _DATED.fullmatch(rest)
                if not m:
                    continue
                try:
                    day = date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
                except ValueError:
                    continue
                k = int(m.group(4)) if m.group(4) else 1
                item = Item(order=(-day.toordinal(), -k), gz=bool(m.group(5)), old=fname,
                            base=fname[: len(fname) - 3] if m.group(5) else fname, day=day, k=k)
                place = (day, k)
            if place in found:
                raise DataError("archives", f"{name}: two archives in the same place: {fname}, {found[place].old}")
            found[place] = item
    return sorted(found.values(), key=lambda i: i.order)


# ------------------------------------------------------------------ the rules

def first_line_time(path: Path) -> datetime | None:
    with path.open("rb") as f:
        line = f.readline()
    line = line.rstrip(b"\r\n") if b" " not in line else line
    token = line.split(b" ", 1)[0]
    try:
        return dates.parse_iso(token.decode("ascii"))
    except UnicodeDecodeError:
        return None


def decide(ctx, name, st: policy.Settings, entry: dict, force: bool) -> str:
    """The reason the stream is rotated, or the reason it is not."""
    path = streams.log_path(ctx.data, name)
    if not path.is_file():
        return "no log"
    size = path.stat().st_size
    if size == 0:
        return "empty"
    if force:
        return "forced"
    if st.max_size is not None and size >= st.max_size:
        return "size"
    if st.max_age is not None:
        if entry.get("opened") is not None:
            opened = dates.parse_state_time(entry["opened"])
        else:
            opened = first_line_time(path)
        if opened is not None and ctx.now - opened >= st.max_age:
            return "age"
    return "not due"


@dataclass
class StreamPlan:
    name: str
    what: str
    lines: list
    removed: list  # file names before the run, newest first
    removes: list  # paths
    moves: list  # (src path, dst path, compress)
    new: tuple | None  # (active path, dst path or None when removed at once, compress)
    entry: dict
    rotated: bool
    n_removed: int
    n_compressed: int


def plan_stream(ctx, name, st: policy.Settings, entry: dict, force: bool) -> StreamPlan:
    logs = streams.logs_dir(ctx.data)
    what = decide(ctx, name, st, entry, force)
    rotated = what in ("forced", "size", "age")
    items = scan(ctx.data, name, st.naming)
    old_archives = entry.get("archives") or {}
    for it in items:
        it.time_text = old_archives.get(it.old)

    new = None
    if rotated:
        if st.naming == "numbered":
            new = Item(order=(0,), gz=False, old=None, time_text=ctx.stamp)
        else:
            day = ctx.now.astimezone(st.offset).date()
            same = [i.k for i in items if i.day == day]
            k = max(same) + 1 if same else 1
            base = f"{name}.log.{day.isoformat()}" + (f".{k}" if k > 1 else "")
            new = Item(order=(-day.toordinal(), -k), gz=False, old=None, base=base, day=day, k=k,
                       time_text=ctx.stamp)
        items = sorted(items + [new], key=lambda i: i.order)

    keep, remaining, removed = st.keep, [], []
    for pos, it in enumerate(items, 1):
        drop = pos > keep
        if not drop and st.keep_days is not None and it.time_text is not None:
            t = dates.parse_state_time(it.time_text)
            drop = ctx.now - t >= st.keep_days * dates.DAY
        (removed if drop else remaining).append(it)

    n_compressed = 0
    for i, it in enumerate(remaining, 1):
        it.compress = not it.gz and i > st.compress_after
        gz = it.gz or it.compress
        n_compressed += it.compress
        if st.naming == "numbered":
            it.final = f"{name}.log.{i}"
        else:
            it.final = it.base
        if gz:
            it.final += ".gz"

    lines, removes, moves = [], [], []
    archives_state = {}
    new_op = None
    for it in remaining:
        if it is new:
            lines.append(f"  new {it.final}")
            new_op = (streams.log_path(ctx.data, name), logs / it.final, it.compress)
        elif it.final != it.old:
            lines.append(f"  {it.final} <- {it.old}")
            moves.append((logs / it.old, logs / it.final, it.compress))
        else:
            lines.append(f"  {it.final}")
        if it.time_text is not None:
            archives_state[it.final] = it.time_text
    removed_old = []
    for it in removed:
        if it is new:
            new_op = (streams.log_path(ctx.data, name), None, False)
            continue
        removed_old.append(it.old)
        lines.append(f"  remove {it.old}")
        removes.append(logs / it.old)

    new_entry = {}
    if entry.get("opened") is not None or "opened" in entry:
        new_entry["opened"] = entry["opened"]
    if rotated:
        new_entry["opened"] = ctx.stamp
    rotations = entry.get("rotations", 0)
    new_entry["rotations"] = rotations + (1 if rotated else 0)
    new_entry["archives"] = archives_state

    return StreamPlan(name, what, lines, removed_old, removes, moves, new_op, new_entry, rotated,
                      len(removed_old), n_compressed)


def _what(plan: StreamPlan) -> str:
    return f"rotate ({plan.what})" if plan.rotated else plan.what


def execute(plans: list[StreamPlan]) -> None:
    # read everything that has to move first, then remove, then write
    writes = []  # (dst, bytes)
    for p in plans:
        for src, dst, compress in p.moves:
            data = src.read_bytes()
            writes.append((dst, gzip.compress(data, mtime=0) if compress else data))
        if p.new is not None:
            active, dst, compress = p.new
            if dst is not None:
                data = active.read_bytes()
                writes.append((dst, gzip.compress(data, mtime=0) if compress else data))
    for p in plans:
        for path in p.removes:
            path.unlink()
        for src, _dst, _c in p.moves:
            src.unlink()
    for dst, data in writes:
        dst.write_bytes(data)
    for p in plans:
        if p.new is not None:
            p.new[0].write_bytes(b"")


def run(ctx, names: list[str], dry_run: bool, force: bool) -> list[str]:
    from logkeep import state

    pol = policy.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(ctx.data)) | pol.streams()
    check_state(doc, existing)
    chosen = sorted(set(names)) if names else sorted(existing)
    for n in chosen:
        if n not in existing:
            raise Refused("unknown-stream", f"no stream {n}")
    plans = []
    for n in chosen:
        entry = doc["streams"].get(n, {})
        plans.append(plan_stream(ctx, n, pol.settings(n), entry, force))

    out = []
    for p in plans:
        out.append(f"{p.name}: {_what(p)}")
        out.extend(p.lines)
    rotated = sum(p.rotated for p in plans)
    removed = sum(p.n_removed for p in plans)
    compressed = sum(p.n_compressed for p in plans)
    out.append(f"{rotated} rotated, {removed} removed, {compressed} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    execute(plans)
    new_doc = dict(doc)
    new_streams = dict(doc["streams"])
    for p in plans:
        new_streams[p.name] = p.entry
    new_doc["streams"] = new_streams
    ctx.state_path.parent.mkdir(parents=True, exist_ok=True)
    state.save(ctx.state_path, new_doc)
    return out

